import XCTest
import PDFKit
@testable import PracovniDenik
final class APIProtocolLogicTests:XCTestCase {
    func testOptionalSectionsDoNotBlockReadiness(){let r:APIValue = .object(["date":.s("2026-11-20"),"work":.s("Kontrola")]);XCTAssertTrue(APIProtocolLogic.missing(r,template:APIProtocolLogic.fallback).isEmpty);XCTAssertEqual(APIProtocolLogic.readiness(r,template:APIProtocolLogic.fallback),1)}
    func testRequiredPhotosAndSignatureAreActual(){let t=APIProtocolLogic.fallback.merged(["signatureRequired":.bool(true),"photosRequired":.bool(true)]),r:APIValue = .object(["date":.s("2026-11-20"),"work":.s("Kontrola"),"customerSignature":.s("png"),"protocolDetails":.object(["signature":.object(["status":.s("absent")])])]);XCTAssertEqual(Set(APIProtocolLogic.missing(r,template:t)),["photos","signature"])}
    func testDecimalQuantityUsesFrozenPrice(){let line=APIFixtureProtocol.material.merged(["itemId":.s("material"),"itemVersion":.n(1),"quantity":.n(1),"priceMinor":.n(199)]);let r=try! APIProtocolLogic.setQuantity("1,5",index:0,lines:.array([line]));XCTAssertEqual(r.array[0]["priceMinor"],.n(199));XCTAssertEqual(APIProtocolPDF.lineTotal(r.array[0]),299);for invalid in ["NaN","-1","0","1.0001","1e2"]{XCTAssertThrowsError(try APIProtocolLogic.quantity(invalid))}}
    func testSelectedActivitiesAreIncludedOnce(){let r:APIValue = .object(["protocolDetails":.object(["activities":.array([.object(["id":.s("a"),"title":.s("Čištění filtrů")])]),"customWork":.s("Vlastní práce")])]);XCTAssertEqual(APIProtocolLogic.work(r),"• Čištění filtrů\nVlastní práce")}
    func testPublicPDFExcludesInternalNotesAndUnselectedPhotos(){let r:APIValue = .object(["notes":.s("Interní"),"photoIds":.array([.s("a"),.s("b")]),"protocolDetails":.object(["photos":.array([.object(["id":.s("b"),"includePDF":.bool(false)])])])]);XCTAssertTrue(APIProtocolExport.customerReport(r)["notes"].string.isEmpty);XCTAssertEqual(APIProtocolExport.photoIDs(r),["a"])}
    func testSignatureFingerprintChangesForMaterialAndCustomerText(){var r:APIValue = .object(["date":.s("2026-11-20"),"protocolDetails":.object(["customWork":.s("Kontrola"),"activities":.array([])])]);let hash=APIProtocolLogic.fingerprint(r);r["notes"] = .s("Interní poznámka");XCTAssertEqual(hash,APIProtocolLogic.fingerprint(r));r["protocolDetails"]["customWork"] = .s("Výměna");XCTAssertNotEqual(hash,APIProtocolLogic.fingerprint(r))}
    func testJobTimeUsesClosedIndividualIntervalsOnly(){let time:APIValue = .object(["workers":.array([.object(["userId":.s("a"),"name":.s("A")]),.object(["userId":.s("b"),"name":.s("B")])]),"intervals":.array([.object(["userId":.s("a"),"kind":.s("work"),"startAt":.n(0),"endAt":.n(3600000)]),.object(["userId":.s("b"),"kind":.s("travel"),"startAt":.n(0),"endAt":.n(1800000)]),.object(["userId":.s("a"),"kind":.s("work"),"startAt":.n(3600000),"endAt":.null])])]);let rows=APIProtocolLogic.timeRows(time);XCTAssertEqual(rows[0]["workMs"],.n(3600000));XCTAssertTrue(rows[0]["open"].bool);XCTAssertEqual(rows[1]["travelMs"],.n(1800000))}
    @MainActor func testAutosaveKeepsDraftAndInvalidatesEditedSignature()async throws{APIFixtureProtocol.reset();APIFixtureProtocol.records["protocol-redesign-fixture"] = .bool(true);let store=APIStore(fixture:true);await store.restore();let model=APIProtocolModel();await model.load(store:store,jobID:"fixture-progress");XCTAssertTrue(model.modern);model.value["report"]["protocolDetails"]["customWork"] = .s("Kontrola");model.sign(.object(["status":.s("signed"),"name":.s("Zákazník"),"signedAt":.number(Date().timeIntervalSince1970*1000)]),png:"png");model.value["report"]["protocolDetails"]["customWork"] = .s("Změna");model.changed(store:store);model.task?.cancel();XCTAssertEqual(model.report["protocolDetails"]["signature"]["status"],.s("invalidated"));XCTAssertTrue(model.report["customerSignature"].string.isEmpty);XCTAssertEqual(store.vault?.state.drafts[model.key]?.value,model.value)}
    @MainActor func testActualCustomerPDFContainsActivitiesAndExcludesInternalNotes()throws{
        let details:APIValue = .object(["schema":.n(1),"template":.object(["name":.s("CUSTOM-TEMPLATE")]),"identity":.object(["customerName":.s("HISTORICAL-CUSTOMER")]),"customWork":.s("Kontrola sekci"),"activities":.array([]),"customerNotes":.bool(false),"timeSnapshot":.object(["workers":.array([.object(["userId":.s("worker"),"name":.s("ACTUAL-WORKER")])]),"intervals":.array([.object(["id":.s("i"),"userId":.s("worker"),"kind":.s("work"),"startAt":.n(0),"endAt":.n(3600000)])])]),"signature":.object(["status":.s("signed"),"name":.s("HISTORICAL-CUSTOMER"),"signedAt":.n(1000),"signedVersion":.n(7)])])
        let r:APIValue = .object(["date":.s("2026-11-20"),"notes":.s("INTERNAL-SECRET"),"materialItems":.array([]),"photoIds":.array([]),"protocolDetails":details])
        let exported=APIProtocolExport.report(r,modern:true),snapshot:APIValue = .object(["job":.object(["title":.s("Servis"),"customerName":.s("CHANGED-CUSTOMER"),"address":.s("Zahradni")])])
        let bytes=try APIProtocolPDF.make(snapshot:APIProtocolExport.snapshot(snapshot,report:exported),report:APIProtocolExport.customerReport(exported));let pdf=try XCTUnwrap(PDFDocument(data:bytes));let text=try XCTUnwrap(pdf.string)
        XCTAssertGreaterThan(pdf.pageCount,0);for required in ["Kontrola sekci","CUSTOM-TEMPLATE","HISTORICAL-CUSTOMER","ACTUAL-WORKER","verze 7"]{XCTAssertTrue(text.contains(required),required)};for privateText in ["INTERNAL-SECRET","CHANGED-CUSTOMER"]{XCTAssertFalse(text.contains(privateText),privateText)}
    }
    @MainActor func testOfflineEditedDraftSurvivesQueueAndAdoptsNewVersion()async throws{APIFixtureProtocol.reset();APIFixtureProtocol.records["protocol-redesign-fixture"] = .bool(true);let store=APIStore(fixture:true);await store.restore();let first=APIProtocolModel();await first.load(store:store,jobID:"fixture-progress");store.online=false;first.value["report"]["protocolDetails"]["customWork"] = .s("Prvni");first.persist(store);await first.save(store:store,finalize:false);XCTAssertEqual(store.outbox.count,1);first.value["report"]["protocolDetails"]["customWork"] = .s("Druha");first.persist(store);let restored=APIProtocolModel();await restored.load(store:store,jobID:"fixture-progress");XCTAssertEqual(restored.report["protocolDetails"]["customWork"],.s("Druha"));store.online=true;await store.sync();restored.syncChanged(store:store);restored.task?.cancel();await restored.save(store:store,finalize:false);XCTAssertTrue(store.outbox.isEmpty);XCTAssertEqual(restored.report["protocolDetails"]["customWork"],.s("Druha"));XCTAssertEqual(restored.value,restored.baseline)}
    @MainActor func testOfflinePhotoAndReportSynchronizeInDependencyOrder()async throws{
        APIFixtureProtocol.reset();APIFixtureProtocol.records["protocol-redesign-fixture"] = .bool(true);let store=APIStore(fixture:true);await store.restore();let model=APIProtocolModel();await model.load(store:store,jobID:"fixture-progress")
        store.online=false;let photo="protocol-offline-photo",photoPath="/api/jobs/fixture-progress/service/photos/"+photo
        try await store.upload(photoPath,bytes:Data([255,216,255,1]),type:"image/jpeg",offline:true,id:photo)
        model.value["report"]["protocolDetails"]["customWork"] = .s("Offline prace s fotografii");model.value["report"]["photoIds"] = .array([.s(photo)]);model.persist(store);await model.save(store:store,finalize:false)
        XCTAssertEqual(store.outbox.count,2);let report=try XCTUnwrap(model.pending(store).first);XCTAssertEqual(report.dependsOn,[photo]);let body=try XCTUnwrap(report.body);XCTAssertEqual(body["report"]["photoIds"],.array([.s(photo)]))
        APIFixtureProtocol.forcedStatus[photoPath]=503;store.online=true;await store.sync();XCTAssertEqual(store.outbox.count,2);XCTAssertNil(APIFixtureProtocol.records["/api/jobs/fixture-progress/report"])
        APIFixtureProtocol.forcedStatus.removeValue(forKey:photoPath);await store.sync();model.syncChanged(store:store);model.task?.cancel()
        XCTAssertTrue(store.outbox.isEmpty);XCTAssertEqual(model.value,model.baseline);XCTAssertEqual(model.report["photoIds"],.array([.s(photo)]));XCTAssertNotNil(APIFixtureProtocol.records[photoPath])
    }

}
